#include <iostream>
using namespace std;

class Student {
public:
    string name;
    void greet() {
        cout << "Hello, " << name << "!" << endl;
    }
};

int main() {
    Student s;
    s.name = "Rupanjana";
    s.greet();
    return 0;
}
